from pathlib import Path
import sys,json,gzip,hashlib,numpy as np
root=Path.cwd();sys.path.insert(0,str(root/'scripts/reinforcement_learning/rsl_rl'))
from diagnose_motion_policy_symmetry import rotation_matrix
from policy_evaluation_evidence import validate_evaluation_bundle
base=root/'learnings/policy_tuning/RobotLab-Isaac-BeyondMimic-Flat-LW-wheel-v0'
runs={'old':('2026-11-05_16-40-14','wheel-to-leg-fixed-start-20261106-001'),'new':('2026-11-06_11-39-51','wheel-to-leg-fixed-start-20261107-001')}
out=base/runs['new'][0]/'evaluations'/runs['new'][1]/'derived'
ref=lambda p:{'path':str(p),'sha256':hashlib.sha256(Path(p).read_bytes()).hexdigest()}
inputs=[];results={};runtimes={}
def envelope(v):
 return {'min':float(min(v)),'max':float(max(v)),'mean':float(np.mean(v))}
for version,(run,batch) in runs.items():
 results[version]={}
 for case in ('nominal','randomized'):
  directory=base/run/'evaluations'/batch/'raw'/f'fixed-start-{case}-a01'
  validate_evaluation_bundle(directory/'result.json')
  inputs.extend([ref(directory/'result.json'),ref(directory/'telemetry.json.gz')])
  with gzip.open(directory/'telemetry.json.gz','rt') as f:t=json.load(f)
  md=t['motion_diagnostics'];runtimes[version,case]=md['initial_runtime'];names=t['joint_names'];fps=md['fps']
  motion_path=Path(md['motion_file']['path']);assert ref(motion_path)['sha256']==md['motion_file']['sha256']
  motion=np.load(motion_path);bi=md['initial_runtime']['body_names'].index('base_link')
  allss=t['samples'];allps=t['physics_samples'];episodes=[];complete=[]
  for ep in sorted(set(s['episode_id'] for s in allss)):
   ss=[s for s in allss if s['episode_id']==ep];ps=[s for s in allps if s['episode_id']==ep]
   terminal=ss[-1]['termination_terms'];success=len(ss)==170 and [s['frame_index'] for s in ss]==list(range(170)) and terminal['motion_finished'] and not any(v for k,v in terminal.items() if k!='motion_finished')
   if success:complete.extend(ss)
   f=np.array([s['frame_index'] for s in ss]);ts=f/fps;z=np.array([s['root_position_w'][2] for s in ss]);zr=motion['body_pos_w'][f,bi,2]
   err=z-zr;vz=np.array([(rotation_matrix(s['root_quaternion_w'])@np.array(s['root_linear_velocity_b']))[2] for s in ss])
   take=(ts>=1.1)&(ts<=1.5);jump=(ts>=1.1)&(ts<=1.7);land=(ts>=1.45)&(ts<=1.9)
   def at(i):
    return {'reference_time_s':float(ts[i]),'physical_time_s':float(ts[i]+.02),'actual_z_m':float(z[i]),'reference_z_m':float(zr[i]),'error_m':float(err[i])}
   im=int(np.abs(err).argmax());il=np.where(land)[0][np.argmin(z[land])]
   iv=np.where(take)[0][np.argmax(vz[take])]
   row={'episode':ep,'successful_complete_cycle':bool(success),'samples':len(ss),'max_abs_height_error':at(im),'landing_min':at(il),'jump_peak_z_m':float(z[jump].max()),'vertical_speed_peak_m_s':float(vz[iv]),'vertical_speed_peak_ref_time_s':float(ts[iv]),'vertical_speed_tracking_rmse_m_s':float(np.sqrt(np.mean((vz[take]-motion['body_lin_vel_w'][f[take],bi,2])**2)))}
   pt=np.array([p['frame_index']/fps+(p['substep']+1)*.005 for p in ps])
   forces=np.array([p['contact_forces_w'] for p in ps]).reshape(-1,4,3);fz=forces[:,:,2]
   ground=np.array([p['ground_contact_forces_w'] for p in ps]).reshape(-1,4,3)[:,:,2]
   contacts=np.concatenate((fz,ground),axis=1);off=(contacts<10).all(axis=1)
   starts=[i for i in range(len(ps)-2) if 1.15<=pt[i]<=1.6 and off[i:i+3].all()]
   firstair=starts[0] if starts else None;contact=None
   if firstair is not None:
    for i in range(firstair+3,len(ps)-2):
     if (fz[i:i+3,:2]>=10).any(axis=1).all():contact=i;break
   row['monitored_air_start_s']=float(pt[firstair]) if firstair is not None else None
   row['first_sustained_foot_contact_s']=float(pt[contact]) if contact is not None else None
   row['monitored_air_interval_ms']=float(round((pt[contact]-pt[firstair])*1000,5)) if contact is not None else None
   row['joint_events']=[]
   for j,n in enumerate(names):
    vv=np.array([p['joint_velocity'][j] for p in ps]);tau=np.array([p['applied_torque'][j] for p in ps]);limit=33 if 'wheel' in n else 10 if 'foot' in n else 20;eff=t['joint_effort_limits'][j]
    over=np.where(np.abs(vv)>limit+1e-5)[0];sat=np.where(np.abs(tau)>=eff*(1-1e-6))[0]
    if len(over) or len(sat):row['joint_events'].append({'joint':n,'overspeed_samples':[{'physical_time_s':float(pt[k]),'velocity_rad_s':float(vv[k])} for k in over],'saturation_samples':[{'physical_time_s':float(pt[k]),'torque_nm':float(tau[k])} for k in sat]})
   episodes.append(row)
  result={'episodes':episodes,'completed':sum(e['successful_complete_cycle'] for e in episodes),'failed':sum(bool(s['done']) and any(v for k,v in s['termination_terms'].items() if k!='motion_finished') for s in allss),'truncated':sum(not any(s['done'] for s in allss if s['episode_id']==e['episode']) for e in episodes)}
  for scope,ee in [('all_cycles',episodes),('completed_cycles',[e for e in episodes if e['successful_complete_cycle']])]:
   result[scope]={'jump_peak_z_m':envelope([e['jump_peak_z_m'] for e in ee]),'vertical_speed_peak_m_s':envelope([e['vertical_speed_peak_m_s'] for e in ee]),'max_abs_height_error_m':max(abs(e['max_abs_height_error']['error_m']) for e in ee),'landing_min_z_m':envelope([e['landing_min']['actual_z_m'] for e in ee]),'foot_contact_time_s':envelope([e['first_sustained_foot_contact_s'] for e in ee if e['first_sustained_foot_contact_s'] is not None]),'monitored_air_interval_ms':envelope([e['monitored_air_interval_ms'] for e in ee if e['monitored_air_interval_ms'] is not None])}
  results[version][case]=result
runtime_comparison={}
for case in ('nominal','randomized'):
 runtime_comparison[case]={}
 for key in ('masses_kg','coms','material_properties','joint_stiffness','joint_damping'):
  a=np.asarray(runtimes['old',case][key]);b=np.asarray(runtimes['new',case][key])
  runtime_comparison[case][key]={'exactly_equal':bool(np.array_equal(a,b)),'max_abs_difference':float(np.max(np.abs(a-b)))}
reference={'motion':ref(motion_path),'jump_peak_z_m':float(motion['body_pos_w'][55:86,bi,2].max()),'upward_vertical_speed_peak_m_s':float(motion['body_lin_vel_w'][:,bi,2].max())}
result={'version':1,'source':CODE_SOURCE,'inputs':inputs,'reference':reference,'statistics':results,'runtime_comparison':runtime_comparison,'conventions':{'height':'base_link world-Z link-origin, actual minus commanded reference frame; control sample occurs 20ms after commanded frame time','velocity':'world-Z base COM velocity reconstructed by quaternion rotation, compared with reference COM velocity','landing':'15ms sustained any-foot Fz >= 10N after first 15ms all-eight monitored Fz <10N; not all-body flight proof','episodes':'complete cycles checked as all frames 0..169 with motion_finished only; truncated sixth cycle reported separately','runtime':'PhysX joint stiffness/damping does not capture software actuator gain/delay draws'}}
with (out/'height-landing-analysis.json').open('x') as f:json.dump(result,f,indent=2,ensure_ascii=False,allow_nan=False);f.write('\n')
print(json.dumps({'reference':reference,'comparison':{v:{c:d['all_cycles'] for c,d in cases.items()} for v,cases in results.items()},'runtime':runtime_comparison},ensure_ascii=False))
